EDGE_FIELDS = ['edge_id', 'optimized_track_id', 'source_track_id', 'left_layer_index', 'right_layer_index', 'left_section_id', 'right_section_id', 'selection_origin', 'median_tre_um', 'p90_tre_um', 'jacobian_min', 'jacobian_p1', 'jacobian_p99', 'inverse_consistency_p90_um', 'matching_status', 'gold_count', 'silver_nucleus_count', 'unknown_count', 'cell_only_count', 'cell_conflict_count', 'edge_output_sha256']
NUCLEUS_LINK_FIELDS = ['edge_id', 'optimized_track_id', 'source_track_id', 'left_layer_index', 'right_layer_index', 'left_roi_layer_id', 'right_roi_layer_id', 'left_section_id', 'right_section_id', 'left_nucleus_id', 'right_nucleus_id', 'left_cell_id', 'right_cell_id', 'quality_class', 'nucleus_method', 'nucleus_iou', 'nucleus_dice', 'nucleus_margin', 'local_residual_px', 'absolute_log_area_ratio', 'cell_relation', 'cell_method', 'cell_score', 'nucleus_supervision_valid', 'cell_supervision_valid', 'accepted', 'audit_status', 'reason_code']
