def pyarrow_schemas() -> dict[str, Any]:
    import pyarrow as pa
    return {'layers': pa.schema([('layer_index', pa.uint32()), ('roi_layer_id', pa.string()), ('optimized_track_id', pa.string()), ('source_track_id', pa.string()), ('section_id', pa.uint16()), ('registered_png_path', pa.string()), ('registered_png_sha256', pa.string()), ('nucleus_mask_path', pa.string()), ('nucleus_mask_sha256', pa.string()), ('cell_mask_path', pa.string()), ('cell_mask_sha256', pa.string()), ('pairs_path', pa.string()), ('pairs_sha256', pa.string()), ('nucleus_count', pa.uint32()), ('raw_cell_count', pa.uint32()), ('valid_cell_count', pa.uint32()), ('artifact_cell_count', pa.uint32()), ('registration_visual_qc', pa.string()), ('segmentation_status', pa.string()), ('algorithm_fingerprint', pa.string())]), 'edges': pa.schema([('edge_id', pa.string()), ('optimized_track_id', pa.string()), ('source_track_id', pa.string()), ('left_layer_index', pa.uint32()), ('right_layer_index', pa.uint32()), ('left_section_id', pa.uint16()), ('right_section_id', pa.uint16()), ('selection_origin', pa.string()), ('median_tre_um', pa.float32()), ('p90_tre_um', pa.float32()), ('jacobian_min', pa.float32()), ('jacobian_p1', pa.float32()), ('jacobian_p99', pa.float32()), ('inverse_consistency_p90_um', pa.float32()), ('matching_status', pa.string()), ('gold_count', pa.uint32()), ('silver_nucleus_count', pa.uint32()), ('unknown_count', pa.uint32()), ('cell_only_count', pa.uint32()), ('cell_conflict_count', pa.uint32()), ('edge_output_sha256', pa.string())]), 'nucleus_links': pa.schema([('edge_id', pa.string()), ('optimized_track_id', pa.string()), ('source_track_id', pa.string()), ('left_layer_index', pa.uint32()), ('right_layer_index', pa.uint32()), ('left_roi_layer_id', pa.string()), ('right_roi_layer_id', pa.string()), ('left_section_id', pa.uint16()), ('right_section_id', pa.uint16()), ('left_nucleus_id', pa.uint32()), ('right_nucleus_id', pa.uint32()), ('left_cell_id', pa.uint32()), ('right_cell_id', pa.uint32()), ('quality_class', pa.string()), ('nucleus_method', pa.string()), ('nucleus_iou', pa.float32()), ('nucleus_dice', pa.float32()), ('nucleus_margin', pa.float32()), ('local_residual_px', pa.float32()), ('absolute_log_area_ratio', pa.float32()), ('cell_relation', pa.string()), ('cell_method', pa.string()), ('cell_score', pa.float32()), ('nucleus_supervision_valid', pa.bool_()), ('cell_supervision_valid', pa.bool_()), ('accepted', pa.bool_()), ('audit_status', pa.string()), ('reason_code', pa.string())])}

def validate_enums(row: dict[str, Any]) -> None:
    if 'quality_class' in row and row['quality_class'] not in QUALITY_CLASSES:
        raise ValueError(f"unknown quality_class {row['quality_class']}")
    if 'cell_relation' in row and row['cell_relation'] not in CELL_RELATIONS:
        raise ValueError(f"unknown cell_relation {row['cell_relation']}")
